static int 
dtb_revolv_help_button_create(
    DtbRevolvPropDialogInfo instance,
    Widget parent
)
{
    XmString	label_xmstring = NULL;
    
    label_xmstring = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 11, 9, "Help"));
    if (instance->help_button == NULL) {
        instance->help_button =
            XtVaCreateWidget("help_button",
                xmPushButtonWidgetClass,
                parent,
                XmNbottomAttachment, XmATTACH_NONE,
                XmNrightOffset, 0,
                XmNrightPosition, 98,
                XmNrightAttachment, XmATTACH_POSITION,
                XmNleftOffset, 0,
                XmNleftPosition, 81,
                XmNleftAttachment, XmATTACH_POSITION,
                XmNtopOffset, 5,
                XmNtopAttachment, XmATTACH_FORM,
                XmNrecomputeSize, True,
                XmNalignment, XmALIGNMENT_CENTER,
                XmNlabelString, label_xmstring,
                NULL);
        /*
         * Add help callback
         */
        XtAddCallback(instance->help_button, XmNactivateCallback,
            dtb_call_help_callback, (XtPointer)instance->prop_dialog_shellform);
        XmStringFree(label_xmstring);
        label_xmstring = NULL;
    }
    if (instance->help_button == NULL)
        return -1;

    return 0;
}

